import { useState } from "react";
import axios from "axios";
import { Bar } from "react-chartjs-2";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Tooltip,
  Legend
} from "chart.js";

ChartJS.register(CategoryScale, LinearScale, BarElement, Tooltip, Legend);

function App() {
  const [owner, setOwner] = useState("");
  const [repo, setRepo] = useState("");
  const [mode, setMode] = useState("daily");

  const [labels, setLabels] = useState([]);
  const [counts, setCounts] = useState([]);
  const [total, setTotal] = useState(0);

  // ✅ NORMAL FETCH (CUSTOM RANGE - BACKEND ALREADY HANDLES)
  const fetchData = async () => {
    const today = new Date().toISOString().slice(0, 10);

    const payload = {
      owner,
      repository: repo,
      startDate: today,
      endDate: today
    };

    const url = `http://localhost:8080/api/pr/${mode}`;

    try {
      const res = await axios.post(url, payload);
      setLabels(res.data.labels);
      setCounts(res.data.counts);
      setTotal(res.data.total);
    } catch (err) {
      alert("Backend Error! Check Console");
      console.error(err);
    }
  };

  // ✅ TODAY BUTTON
  const fetchToday = async () => {
    const today = new Date().toISOString().slice(0, 10);

    const payload = {
      owner,
      repository: repo,
      startDate: today,
      endDate: today
    };

    try {
      const res = await axios.post(
        "http://localhost:8080/api/pr/daily",
        payload
      );
      setLabels(res.data.labels);
      setCounts(res.data.counts);
      setTotal(res.data.total);
    } catch (err) {
      alert("Today Fetch Failed");
      console.error(err);
    }
  };

  // ✅ BAR CHART DATA
  const data = {
    labels: labels,
    datasets: [
      {
        label: "Pull Requests",
        data: counts,
        backgroundColor: "#4F46E5"
      }
    ]
  };

  return (
    <div style={styles.container}>
      <h1 style={styles.heading}>GitHub Analytics Dashboard</h1>

      {/* ✅ GITHUB LOGIN BUTTON (NEXT STEP READY) */}
      <button
        style={styles.loginBtn}
        onClick={() => window.location.href = "http://localhost:8080/auth/github"}
      >
        Login with GitHub
      </button>

      <div style={styles.form}>
        <input
          placeholder="GitHub Username"
          value={owner}
          onChange={(e) => setOwner(e.target.value)}
        />

        <input
          placeholder="Repository"
          value={repo}
          onChange={(e) => setRepo(e.target.value)}
        />

        <select onChange={(e) => setMode(e.target.value)}>
          <option value="daily">Daily</option>
          <option value="monthly">Monthly</option>
          <option value="yearly">Yearly</option>
        </select>

        <button onClick={fetchData}>Track</button>
        <button onClick={fetchToday}>Today</button>
      </div>

      {total > 0 && (
        <>
          <h2>Total PRs: {total}</h2>
          <div style={{ width: "90%", maxWidth: 950 }}>
            <Bar data={data} />
          </div>
        </>
      )}
    </div>
  );
}

const styles = {
  container: {
    textAlign: "center",
    padding: 30,
    fontFamily: "Arial",
    background: "#F8FAFC",
    minHeight: "100vh"
  },
  heading: {
    color: "#1E293B"
  },
  form: {
    display: "flex",
    gap: 10,
    justifyContent: "center",
    marginBottom: 30,
    flexWrap: "wrap"
  },
  loginBtn: {
    padding: "10px 20px",
    borderRadius: 6,
    border: "none",
    background: "#111827",
    color: "white",
    fontWeight: "bold",
    cursor: "pointer",
    marginBottom: 20
  }
};

export default App;
